tasks.command:
docker compose exec -T worker python -c "import os,glob; hits=[]; 
for d in glob.glob('/proc/[0-9]*'):
  try:
    cmd=open(d+'/cmdline','rb').read().replace(b'\x00',b' ').decode('utf-8','ignore').strip()
    if 'ffmpeg' in cmd:
      hits.append((int(d.split('/')[-1]),cmd))
  except Exception:
    pass
hits.sort();
print('\n'.join([f'{pid} {cmd}' for pid,cmd in hits]) or 'NO_FFMPEG')"
